import{_ as t,a as o,b as i}from"./chunks/mrizka_s_ikonami2.DbRMQcgy.js";import{_ as n,o as s,c as r,j as e,a as l,aa as c}from"./chunks/framework.BAs_AphD.js";const u="/buildary-help-preview/media/en/firstofall/en_wwwbuildary.png",d="/buildary-help-preview/media/en/firstofall/en_prihlaseni.png",p="/buildary-help-preview/media/en/firstofall/en_aktivace_uctu.png",h="/buildary-help-preview/media/en/firstofall/en_zapomenute-heslo.png",g="/buildary-help-preview/media/en/firstofall/en_azuread.png",m="/buildary-help-preview/media/en/firstofall/en_rozcestnik.png",f="/buildary-help-preview/media/en/firstofall/en_sprava-uctu2.png",z=JSON.parse('{"title":"Access to the Application","description":"","frontmatter":{"title":"Access to the Application","wiki":"en:firstofall:access"},"headers":[],"relativePath":"en/firstofall/access.md","filePath":"en/firstofall/access.md","lastUpdated":1794388980000}'),y={name:"en/firstofall/access.md"};function w(b,a,A,v,_,k){return s(),r("div",null,[...a[0]||(a[0]=[e("h1",{id:"access-to-the-application",tabindex:"-1"},[l("Access to the Application "),e("a",{class:"header-anchor",href:"#access-to-the-application","aria-label":'Permalink to "Access to the Application"'},"​")],-1),e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/vvuLgeMZrmQ",title:"YouTube video",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),c('<h2 id="first-launch" tabindex="-1">First Launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First Launch&quot;">​</a></h2><figure class="shot" style="--w:600px;"><img src="'+u+'" alt="Login Form" width="300" loading="lazy"></figure><p>We recommend launching <strong>Buildary</strong> from the <a href="https://buildary.online" target="_blank" rel="noreferrer">www.buildary.online</a> website, where the latest information related to the application and its practical use is also published.</p><p>To sign in to your account, click the blue <strong>Sign In</strong> button in the upper-right corner.</p><p><strong>If you do not have an account yet, you must create one first.</strong> You can register a new account from this website by clicking the yellow-orange <strong>30-DAY FREE DEMO</strong> button.</p><h2 id="creating-an-account-using-an-email-address-and-activation-code" tabindex="-1">Creating an Account Using an Email Address and Activation Code <a class="header-anchor" href="#creating-an-account-using-an-email-address-and-activation-code" aria-label="Permalink to &quot;Creating an Account Using an Email Address and Activation Code&quot;">​</a></h2><figure class="shot" style="--w:400px;"><img src="'+d+'" alt="" width="400" loading="lazy"></figure><p>If you do not have an account yet, you can create one by selecting <strong>Create a New Account</strong> in the login window, or by clicking the yellow-orange <strong>30-DAY FREE DEMO</strong> button on the home page (see above).</p><img src="'+p+'" alt="" width="400" loading="lazy"> After creating a new account, a message containing an activation code will be sent to your email address. <p>After activation, you can use the account to work in all modules of the <strong>Buildary</strong> application.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You do not need to sign in every time you launch Buildary. If you select the &quot;Remember me&quot; option, the application will not ask you to sign in again. However, this only applies while the so-called token, which is a temporary access code, remains valid. Once the token expires, you must sign in again. The token is valid for 1 month.</p></div><h2 id="forgotten-password" tabindex="-1">Forgotten Password <a class="header-anchor" href="#forgotten-password" aria-label="Permalink to &quot;Forgotten Password&quot;">​</a></h2><figure class="shot" style="--w:400px;"><img src="'+h+'" alt="" width="400" loading="lazy"></figure><p>If you forget your password, click <strong>Forgot Password</strong> in the login window. The link will redirect you to the password recovery form, where you enter your email address and confirm by clicking <strong>Send</strong>. Then follow the instructions sent to your email address.</p><h2 id="accessing-the-application-via-azure-ad" tabindex="-1">Accessing the Application via Azure AD <a class="header-anchor" href="#accessing-the-application-via-azure-ad" aria-label="Permalink to &quot;Accessing the Application via Azure AD&quot;">​</a></h2><figure class="shot" style="--w:400px;"><img src="'+g+'" alt="" width="400" loading="lazy"></figure><p>You can access Buildary via Azure AD. In this case, you do not need to enter your email address and password in the login form. Simply select <strong>Sign in with Azure AD</strong> and then sign in to your Microsoft account. To access Buildary, you must grant the Buildary application access to your Azure AD account data (name and email address). Without this permission, your account cannot be linked and you cannot work in Buildary.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>If the user does not yet have a Buildary account, one will be created automatically.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>IMPORTANT!</strong> The first time you sign in to Buildary using an Azure AD account, the option to access the application using an <strong>email address and password is deactivated</strong>. This means that once a user accesses Buildary via Azure AD, they must use this method exclusively (this also applies to the mobile application). It does not matter whether the account was originally activated through the Buildary registration form or through Azure AD. Signing in by entering an email address and password will no longer be available.</p></div><h2 id="first-access-to-the-application" tabindex="-1">First Access to the Application <a class="header-anchor" href="#first-access-to-the-application" aria-label="Permalink to &quot;First Access to the Application&quot;">​</a></h2><figure class="shot" style="--w:600px;"><img src="'+m+'" alt="" width="200" loading="lazy"></figure><p>After signing in to your account, you can enter the application and, on your first login, have a Demo Project generated for you. We recommend using this option. The application will not offer it again on subsequent logins. More information about the Demo Project can be found in a separate section of the Help.</p><h2 id="account-management" tabindex="-1">Account Management <a class="header-anchor" href="#account-management" aria-label="Permalink to &quot;Account Management&quot;">​</a></h2><figure class="shot" style="--w:200px;"><img src="'+t+'" alt="" width="200" loading="lazy"></figure><p>Clicking the user icon (profile picture) in the upper-right corner displays a window with the name and email address of the signed-in account, as well as an option to log out of the application. To manage your account, click your name.</p><figure class="shot" style="--w:400px;"><img src="'+f+'" alt="" width="400" loading="lazy"></figure><p>In the <strong>Account</strong> window, you can edit your personal information and add a profile picture.</p><p>The <strong>Change Password</strong> button allows you to change your password.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>We strongly recommend using profile pictures. In the Project Diary and Ticket Management modules, profile icons are used in many places and significantly improve clarity and the overall visual experience when working with the Buildary application.</p></div><h2 id="using-the-profile-icon" tabindex="-1">Using the Profile Icon <a class="header-anchor" href="#using-the-profile-icon" aria-label="Permalink to &quot;Using the Profile Icon&quot;">​</a></h2><figure class="shot" style="--w:600px;"><img src="'+o+'" alt="" width="400" loading="lazy"></figure><p>Example of the profile icon being used in the Project Diary module to identify the author of an additional record.</p><figure class="shot" style="--w:600px;"><img src="'+i+'" alt="" width="400" loading="lazy"></figure><p>Example of the profile icon being used in the Ticket Management module.</p><h2 id="deleting-an-account" tabindex="-1">Deleting an Account <a class="header-anchor" href="#deleting-an-account" aria-label="Permalink to &quot;Deleting an Account&quot;">​</a></h2><p>If you decide to stop using Buildary altogether and <strong>delete your account</strong>, contact us at <strong><a href="mailto:buildary@firstis.eu" target="_blank" rel="noreferrer">buildary@firstis.eu</a></strong> to request its deletion.</p>',37)])])}const T=n(y,[["render",w]]);export{z as __pageData,T as default};
